import os
import torch

# ==========================================
# Path Configuration
# ==========================================
# Root directory for input data (Read-Only)
INPUT_DIR = "./input"

# Metadata files generated by the analysis step
METADATA_DIR = "./metadata"
TRAIN_CSV = os.path.join(METADATA_DIR, "train_metadata.csv")
VAL_CSV = os.path.join(METADATA_DIR, "val_metadata.csv")
TEST_CSV = os.path.join(METADATA_DIR, "test_metadata.csv")

# Working directory for outputs (Read/Write)
WORKING_DIR = "./working"
IDEA_DIR = os.path.join(WORKING_DIR, "idea_12")

# Sub-directories for caching and model artifacts
CACHE_DIR = os.path.join(IDEA_DIR, "cache")
CHECKPOINT_DIR = os.path.join(IDEA_DIR, "checkpoints")
SUBMISSION_DIR = os.path.join(IDEA_DIR, "submission")

# Ensure writeable directories exist
os.makedirs(CACHE_DIR, exist_ok=True)
os.makedirs(CHECKPOINT_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# ==========================================
# Data Configuration
# ==========================================
# Random seed for reproducibility
SEED = 42

# Target variables to predict
TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]

# Compositional features for the MLP stream
# Based on data analysis, these are the explicit columns available
COMPOSITION_COLS = ["percent_atom_al", "percent_atom_ga", "percent_atom_in"]

# Graph construction parameters
# Strictly enforce 5.0 Angstrom cutoff as per solution strategy
CUTOFF_RADIUS = 5.0
# Maximum number of neighbors to consider for graph edges
MAX_NEIGHBORS = 12

# ==========================================
# Model Architecture Hyperparameters
# ==========================================
# Dimension of node embeddings and hidden layers
EMBEDDING_DIM = 64

# Number of Graph Convolution layers (CGCNN blocks)
N_CONV_LAYERS = 4

# Number of Gaussian RBF basis functions for edge features
N_RBF = 60

# Dropout rate for regularization
DROPOUT = 0.1

# ==========================================
# Training Hyperparameters
# ==========================================
# Batch size (chosen to introduce beneficial gradient noise)
BATCH_SIZE = 48

# Initial learning rate
LEARNING_RATE = 1e-3

# Weight decay for AdamW optimizer
WEIGHT_DECAY = 1e-4

# Maximum number of training epochs
NUM_EPOCHS = 150

# Early stopping patience (epochs without improvement)
PATIENCE = 15

# Device configuration
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

# Number of workers for data loading
NUM_WORKERS = 4

# Debugging: Set to a small number to limit dataset size during development (None for full run)
DEBUG_SAMPLE_SIZE = None
